import{_ as s,c as i,o as n,ag as e}from"./chunks/framework.DPDPlp3K.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"old/manjaro安装后必须做的事情.md","filePath":"old/manjaro安装后必须做的事情.md"}'),t={name:"old/manjaro安装后必须做的事情.md"};function o(l,a,r,p,c,h){return n(),i("div",null,a[0]||(a[0]=[e(`<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>实用工具折腾记：Manjaro 安装后必须做的事情</li><li>手把手教你：Manjaro 安装后必须做的事情，少走一些配置弯路</li><li>Manjaro 安装后必须做的事情怎么用？这篇把关键步骤讲清楚</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章面向喜欢折腾工具和开发环境的同学，围绕「Manjaro 安装后必须做的事情」整理关键步骤、配置点和注意事项，方便按需复用。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群 群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源 关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>工具类文章最重要的价值，就是让你下次遇到同类场景时能直接复用。</strong></p><p>无论是开发环境、系统配置，还是小工具折腾，真正耗时间的往往都是那些不起眼的细节。</p><p>这篇围绕「Manjaro 安装后必须做的事情」把原始操作笔记整理成更清晰的步骤版，方便大家按需参考。</p><h2 id="操作步骤整理" tabindex="-1">操作步骤整理 <a class="header-anchor" href="#操作步骤整理" aria-label="Permalink to &quot;操作步骤整理&quot;">​</a></h2><p>下面进入具体内容。工具类配置建议一步一步来，改完一个关键点就验证一次结果。</p><p>如果你也遇到类似配置场景，可以先按本文步骤跑通，再根据自己的环境微调。</p><h2 id="系统版本" tabindex="-1">系统版本 <a class="header-anchor" href="#系统版本" aria-label="Permalink to &quot;系统版本&quot;">​</a></h2><h2 id="更换国内源" tabindex="-1">更换国内源 <a class="header-anchor" href="#更换国内源" aria-label="Permalink to &quot;更换国内源&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pacman-mirrors</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -i</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -c</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> China</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -m</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> rank</span></span></code></pre></div><h2 id="添加-archlinuxcn-源-antergos源-arch4edu源" tabindex="-1">添加 archlinuxcn 源,antergos源,arch4edu源 <a class="header-anchor" href="#添加-archlinuxcn-源-antergos源-arch4edu源" aria-label="Permalink to &quot;添加 archlinuxcn 源,antergos源,arch4edu源&quot;">​</a></h2><ul><li><p>编辑 <code>/etc/pacman.conf</code> 添加以下内容</p><div class="language-code vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">code</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>[archlinuxcn]</span></span>
<span class="line"><span>SigLevel = Optional TrustedOnly</span></span>
<span class="line"><span>#中科大源</span></span>
<span class="line"><span>Server = https://mirrors.ustc.edu.cn/archlinuxcn/$arch</span></span>
<span class="line"><span>#清华源</span></span>
<span class="line"><span>Server = https://mirrors.tuna.tsinghua.edu.cn/archlinuxcn/$arch</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[antergos]</span></span>
<span class="line"><span>SigLevel = TrustAll</span></span>
<span class="line"><span>Server = https://mirrors.tuna.tsinghua.edu.cn/antergos/$repo/$arch</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[arch4edu]</span></span>
<span class="line"><span>SigLevel = TrustAll</span></span>
<span class="line"><span>Server = https://mirrors.tuna.tsinghua.edu.cn/arch4edu/$arch</span></span></code></pre></div></li><li><p>防止签名错误</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pacman</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -S</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> archlinuxcn-keyring</span></span></code></pre></div></li></ul><h2 id="更新源列表" tabindex="-1">更新源列表 <a class="header-anchor" href="#更新源列表" aria-label="Permalink to &quot;更新源列表&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pacman-mirrors</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -g</span></span></code></pre></div><h2 id="更新系统" tabindex="-1">更新系统 <a class="header-anchor" href="#更新系统" aria-label="Permalink to &quot;更新系统&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">sudo</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pacman</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -Syyu</span></span></code></pre></div><h2 id="安装软件" tabindex="-1">安装软件 <a class="header-anchor" href="#安装软件" aria-label="Permalink to &quot;安装软件&quot;">​</a></h2><ul><li><p><code>sudo pacman -S base-devel</code></p></li><li><p>包管理工具 <strong>yay</strong> <code>sudo pacman -S yay</code></p></li><li><p>显示有关相应系统的简要信息工具 <strong>neofetch</strong> <code>yay -S neofetch</code></p></li><li><p>谷歌浏览器 <code>yay -S google-chrome</code></p></li><li><p><strong>neovim</strong> <code>yay -S neovim</code></p></li><li><p>中文输入法 <strong>fcitx-im</strong> <code>yay -S fcitx-im</code></p><ul><li><p>设置 IM 环境变量</p></li><li><p><code>nvim ~/.pam_environment</code> 添加以下内容</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>GTK_IM_MODULE DEFAULT=fcitx</span></span>
<span class="line"><span>QT_IM_MODULE  DEFAULT=fcitx</span></span>
<span class="line"><span>XMODIFIERS    DEFAULT=\\@im=fcitx</span></span></code></pre></div></li><li><p>重启电脑</p></li></ul></li><li><p>安装 fcitx 的GUI配置工具 <code>yay -S kcm-fcitx fcitx-configtool</code></p></li><li><p>Fcitx 自带剪贴板，其快捷键为 <code>Ctrl + ;</code>, 小小功能拯救世界。</p></li><li><p>云拼音 <strong>fcitx-cloudpinyin</strong> <code>yay -S fcitx-cloudpinyin</code></p><ul><li>安装好后重启fcitx,进入配置切换云拼音来源为百度，默认是Google</li></ul></li><li><p>终端文件管理器 <strong>ranger</strong> <code>yay -S ranger</code></p></li><li><p>windows模拟器 <strong>wine</strong> <code>yay -S wine wine-gecko wine-mono</code></p></li><li><p><strong>ocs-url</strong> <code>yay -S ocs-url</code></p></li><li><p><strong>nodejs</strong> <code>yay -S nodejs npm</code></p></li><li><p>deb包转换工具 <strong>debtap</strong> <code>yay -S debtap</code></p></li><li><p><strong>dmenu</strong> <strong>rofi</strong> <strong>feh</strong> <strong>picom</strong> <strong>w3m</strong> <strong>python-pip</strong> <strong>bat</strong></p></li><li><p><strong>deepin-wine-qq</strong> 安装好后是一个安装包，安装包安装好后重启系统或者等一会才能打开，不然会报错，报错就重启系统就行了</p></li><li><p><strong>ffmpegthumbnailer</strong></p></li><li><p><strong>mpv</strong> <strong>ttf-font-awesome</strong> <strong>ttf-font-icons</strong></p></li><li><p><strong>xorg-xrandr</strong></p></li><li><p><strong>gvim</strong></p></li><li><p><code>pip install quickswitch-i3 i3-py</code> 在用demu的时候使用的脚本</p></li><li><p><code>yay -S wqy-microhei wqy-bitmapfont wqy-zenhei wqy-microhei-li</code></p></li><li><p><code>yay -S adobe-source-han-sans-cn-fonts adobe-source-han-serif-cn-fonts</code></p></li></ul><h2 id="配置zsh" tabindex="-1">配置zsh <a class="header-anchor" href="#配置zsh" aria-label="Permalink to &quot;配置zsh&quot;">​</a></h2><h3 id="安装oh-my-zsh" tabindex="-1">安装oh-my-zsh <a class="header-anchor" href="#安装oh-my-zsh" aria-label="Permalink to &quot;安装oh-my-zsh&quot;">​</a></h3><ul><li><code>git clone https://gitee.com/huang_jian_hua/oh-my-zsh.git</code></li><li>运行 <code>oh-my-zsh/tools/install.sh</code></li><li>安装完毕删除 <strong>oh-my-zsh</strong> 文件夹</li><li>使用<strong>konsole</strong>的需手动更改bash为zsh</li></ul><h3 id="安装语法高亮和自动建议插件" tabindex="-1">安装语法高亮和自动建议插件 <a class="header-anchor" href="#安装语法高亮和自动建议插件" aria-label="Permalink to &quot;安装语法高亮和自动建议插件&quot;">​</a></h3><ul><li><p>oh-my-zsh插件安装方法</p><ol><li>将插件放到<code>~/.oh-my-zsh/custom/plugins/</code>下</li><li>在配置文件<code>~/.zshrc</code>里添加插件名称</li></ol></li><li><p>进入 <code>~/.oh-my-zsh/custom/plugins/</code></p></li><li><p>自动建议 <code>git clone https://gitee.com/huang_jian_hua/zsh-autosuggestions.git</code></p></li><li><p>语法高亮 <code>git clone https://gitee.com/huang_jian_hua/zsh-syntax-highlighting.git</code></p></li><li><p>配置文件 <strong>71行</strong> 修改为<code>plugins=(git zsh-syntax-highlighting zsh-autosuggestions)</code></p></li><li><p>重启终端</p></li></ul><h3 id="配置zsh主题" tabindex="-1">配置zsh主题 <a class="header-anchor" href="#配置zsh主题" aria-label="Permalink to &quot;配置zsh主题&quot;">​</a></h3><ul><li><code>.zshrc</code> 文件第<strong>11</strong>行 <code>ZSH_THEME=&quot;robbyrussell&quot;</code></li><li>修改成<strong>random</strong>为随机主题</li><li>可填参数在<code>~/.oh-my-zsh/themes</code>文件夹里面可自行查看</li><li>自定义的主题应该放在<code>~/.oh-my-zsh/custom/themes</code></li></ul><h2 id="配置ranger" tabindex="-1">配置ranger <a class="header-anchor" href="#配置ranger" aria-label="Permalink to &quot;配置ranger&quot;">​</a></h2><ul><li>生成配置文件 <ul><li><code>ranger --copy-config=all</code></li></ul></li><li>安装文件图标 <ul><li>终端字体需换成Nerd Font字体</li><li>运行以下两句命令 <ul><li><code>git clone https://gitee.com/huang_jian_hua/ranger_devicons.git ~/.config/ranger/plugins/ranger_devicons</code></li><li><code>echo &quot;default_linemode devicons&quot; &gt;&gt; $HOME/.config/ranger/rc.conf</code></li></ul></li><li>重启ranger</li></ul></li><li>修改配置文件 <strong>rc.conf</strong> 和 <strong>scope.sh</strong></li></ul><h2 id="美化折腾" tabindex="-1">美化折腾 <a class="header-anchor" href="#美化折腾" aria-label="Permalink to &quot;美化折腾&quot;">​</a></h2><h3 id="动态壁纸" tabindex="-1">动态壁纸 <a class="header-anchor" href="#动态壁纸" aria-label="Permalink to &quot;动态壁纸&quot;">​</a></h3><ol><li><p>右键桌面 <a href="https://imgtu.com/i/gYPh0f" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/05/09/gYPh0f.png" alt="gYPh0f.png"></a></p></li><li><p>获取新插件 <a href="https://imgtu.com/i/gYPRXt" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/05/09/gYPRXt.png" alt="gYPRXt.png"></a></p></li><li><p>安装插件 <a href="https://imgtu.com/i/gYPfnP" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/05/09/gYPfnP.png" alt="gYPfnP.png"></a></p></li><li><p>选择壁纸类型 <a href="https://imgtu.com/i/gYP26I" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/05/09/gYP26I.png" alt="gYP26I.png"></a></p></li><li><p>选择视频文件 <a href="https://imgtu.com/i/gYPg1A" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/05/09/gYPg1A.png" alt="gYPg1A.png"></a></p></li></ol><h2 id="如果是在vmware的话-安装open-vm-tools" tabindex="-1">如果是在vmware的话,安装open-vm-tools <a class="header-anchor" href="#如果是在vmware的话-安装open-vm-tools" aria-label="Permalink to &quot;如果是在vmware的话,安装open-vm-tools&quot;">​</a></h2><p><code>yay -S open-vm-tools</code><code>systemctl enable vmtoolsd.service</code><code>systemctl start vmtoolsd.service</code></p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你有没有折腾过「Manjaro 安装后必须做的事情」这类工具或环境配置？如果有更省事的方案，也欢迎在评论区补充。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>Manjaro、软件使用和配置、Linux、工具配置、效率工具</p>`,49)]))}const u=s(t,[["render",o]]);export{g as __pageData,u as default};
